struct Todo {
    id: u32,
    title: String,
    done: bool,
}

impl Todo {
    fn new(id: u32, title: &str) -> Self {
        Self { id, title: title.to_string(), done: false }
    }
    fn complete(&mut self) {
        self.done = true;
    }
}

fn main() {
    let mut list = vec![Todo::new(1, "learn structs"), Todo::new(2, "ship app")];
    list[0].complete();
    for t in &list {
        let mark = if t.done { 'x' } else { ' ' };
        println!("[{mark}] #{} {}", t.id, t.title);
    }
}
